const S = s => Math.round(s * 1000);              // seconds -> ms
let _eid = 0;

/**
 * One timeline event.
 * kind : message | run | llm | tool | subtask | persist | socket | error
 * lane : events | turn | llm | tools | subtasks | io
 */
function ev(kind, lane, label, start, dur, status, meta) {
  return {
    id: 'e' + (++_eid),
    kind, lane, label,
    start: S(start),
    dur: dur == null ? null : S(dur),
    status: status || 'ok',
    meta: meta || {}
  };
}

/* MOCK: turn 1 — a healthy turn (no anomalies) */
