const entries=[...document.querySelectorAll('.notion-entry')];
const rows=[];
entries.forEach((entry,i)=>{
  const header=[...entry.querySelectorAll('div')].find(d=>d.className&&String(d.className).includes('sticky')&&String(d.className).includes('top-0'));
  const strip=entry.querySelector('.rounded-full.border');
  if(!strip) return;
  rows.push({
    i,
    inHeader: !!header && header.contains(strip),
    segs: strip.querySelectorAll('[style*="width"]').length,
    counter: strip.textContent.replace(/\s+/g,' ').trim().slice(0,80),
    colors: [...new Set([...strip.querySelectorAll('[style*="width"]')].slice(0,40).map(d=>getComputedStyle(d).backgroundColor))]
  });
});
return {url:location.href, total: entries.length, strips: rows.length, sample: rows.slice(-3), headerCols: document.querySelectorAll('.notion-entry div.sticky').length};

const entry=[...document.querySelectorAll('.notion-entry')][2];
const btn=entry.querySelector('.rounded-full.border button');
btn.click();
await new Promise(r=>setTimeout(r,400));
const panel=entry.querySelector('[id^="events-panel"]');
const tabs=panel?[...panel.querySelectorAll('[role="tab"]')].map(t=>({t:t.textContent.replace(/\s+/g,' ').trim(), sel:t.getAttribute('aria-selected')})):null;
return {opened:!!panel, inHeader: !!panel && panel.closest('div.sticky')!==null, tabs, firstRows: panel?[...panel.querySelectorAll('tbody tr')].slice(0,6).map(tr=>[...tr.children].map(td=>td.textContent.replace(/\s+/g,' ').trim()).join(' | ')):null};

const entry=[...document.querySelectorAll('.notion-entry')][2];
const btn=entry.querySelector('.rounded-full.border button');
btn.click();
return new Promise(resolve=>setTimeout(()=>{
  const panel=entry.querySelector('[id^="events-panel"]');
  const tabs=panel?[...panel.querySelectorAll('[role="tab"]')].map(t=>({t:t.textContent.replace(/\s+/g,' ').trim(), sel:t.getAttribute('aria-selected')})):null;
  resolve({opened:!!panel, inHeader: !!panel && panel.closest('div.sticky')!==null, tabs, firstRows: panel?[...panel.querySelectorAll('tbody tr')].slice(0,6).map(tr=>[...tr.children].map(td=>td.textContent.replace(/\s+/g,' ').trim()).join(' | ')):null});
},500));

const panel=document.querySelector('[id^="events-panel"]');
const tab=[...panel.querySelectorAll('[role="tab"]')].find(t=>t.textContent.includes('Events'));
tab.click();
return new Promise(resolve=>setTimeout(()=>{
  const rows=[...panel.querySelectorAll('tbody tr')].map(tr=>[...tr.children].map(td=>td.textContent.replace(/\s+/g,' ').trim()).join(' | '));
  const legend=[...panel.querySelectorAll('.rounded-full')].slice(0,8).map(d=>d.textContent.replace(/\s+/g,' ').trim());
  resolve({n:rows.length, first:rows.slice(0,8), last:rows.slice(-3), legend});
},400));

