return (async () => {
  const panel = document.querySelector('[id^="events-panel-"]');
  const row = panel.querySelector('[role="button"][aria-expanded]');
  const span = [...row.children[1].querySelectorAll('span')].find(s => /[:=]/.test(s.textContent) && s.className.includes('font-mono'));
  const before = getComputedStyle(span).display;
  const cls = span.className;
  span.classList.remove('hidden');
  const withoutHidden = getComputedStyle(span).display;
  span.className = cls;
  // order of the two rules in the stylesheet
  let order = [];
  const walk = (rules) => {
    for (const r of rules) {
      const t = r.cssText || '';
      if (/^\.hidden\b/.test(t.trim()) || t.startsWith('.hidden')) order.push('hidden:' + t.slice(0, 40));
      if (r.cssText.startsWith('@container panel (width >= 24rem)') && r.cssRules && [...r.cssRules].some(x => x.cssText.includes('display: inline'))) order.push('@container-24rem-inline');
      if (r.cssRules) { try { walk(r.cssRules) } catch {} }
    }
  };
  for (const s of document.styleSheets) { try { walk(s.cssRules) } catch {} }
  return { before, withoutHidden, className: cls, order: order.slice(0, 6), orderLen: order.length };
})();

