<script>
  // ── direction switch ────────────────────────────────────────────────
  const tabs = document.querySelectorAll('#tabs button');
  function setVariant(v){
    document.body.dataset.variant = v;
    tabs.forEach(b => b.setAttribute('aria-pressed', String(b.dataset.target === v)));
  }
  tabs.forEach(b => b.addEventListener('click', () => setVariant(b.dataset.target)));

  // ── deterministic waterfall (identical across the 3 specimens) ──────
  // MOCK: a real turn comes from the events table; this is a fixed pattern so
  // the three variants can be compared pixel for pixel.
  function renderTrack(track){
    let s = 20251113;
    const rnd = () => ((s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
    const pool = ['read','read','read','read','web','web','exec','write','agent'];
    const frag = document.createDocumentFragment();
    let count = 0;
    for (let i = 0; i < 138; i++) {
      // every 7th slot is model "thinking" (no tool call) → the hatched gaps
      const fam = (i % 7 === 3) ? 'model' : pool[Math.floor(rnd() * pool.length)];
      const el = document.createElement('span');
      el.className = 'sg ' + fam;
      el.style.flex = (fam === 'model' ? 1 + rnd() * 2.2 : 0.9 + rnd() * 2.6).toFixed(2);
      if (i === 96) { el.className = 'sg error'; el.style.flex = '1.4'; el.title = 'explain_image failed'; }
      frag.appendChild(el);
      count++;
    }
    track.appendChild(frag);
  }
  document.querySelectorAll('[data-tl]').forEach(renderTrack);

  // ── trigger toggles the surface it owns ─────────────────────────────
  document.querySelectorAll('.act-trigger').forEach(btn => {
    btn.addEventListener('click', () => {
      const variant = document.body.dataset.variant;
      const target = variant === 'a' ? '#mA' : variant === 'b' ? '#mB' : '#tbC';
      const el = document.querySelector(target);
      if (!el) return;
      const open = el.style.display !== 'none';
      el.style.display = open ? 'none' : (target === '#tbC' ? 'flex' : 'block');
      btn.setAttribute('aria-expanded', String(!open));
    });
  });
</script>
</body>
</html>

