      <span class="it"><span class="sw model"></span>model</span>
      <span class="it"><span class="sw read"></span>read</span>
      <span class="it"><span class="sw write"></span>write</span>
      <span class="it"><span class="sw exec"></span>execute</span>
      <span class="it"><span class="sw web"></span>web</span>
      <span class="it"><span class="sw error"></span>error</span>
