  // Computed from the recorded events only, never guessed: it names what the
  // turn is waiting for and how long ago the last event was written, so a two
  // minute wait for the model is visibly different from a dead turn.
  healthBanner() {
    const message = this.message || {}
    const meta = message.meta_data || {}
    const lastAt = this.latestEventAt
    const silentMs = lastAt != null ? Math.max(0, Date.now() - lastAt) : null
    const silent = silentMs != null ? this.formatDuration(silentMs) : null
    const openTool = [...this.toolEvents].reverse().find(tool => tool.status === 'running')
    const openPhase = [...this.phaseEvents].reverse().find(phase => phase.status === 'running')

    // The process died while this turn was running (power off, restart, kill).
    if (meta.interrupted) {
      const at = this.parseTime(meta.interrupted_at)
      const when = at != null
        ? ' at ' + new Date(at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
        : ''
