      return entries.map((entry, index) => {
        const widthPct = (entry.ms / span) * 100
        const segment = {
          ...entry,
          key: `${entry.kind}-${index}`,
          width: widthPct + '%',
          leftPct: left,
          spanPct: widthPct,
