      if (this.tools.length) {
        parts.push(`${this.tools.length} tool${this.tools.length > 1 ? 's' : ''}`)
      }
      if (this.toolErrorCount) {
        parts.push(`${this.toolErrorCount} error${this.toolErrorCount > 1 ? 's' : ''}`)
