      return Object.entries(meta)
        .filter(([, value]) => value != null && value !== '')
        .slice(0, this.maxTipArgs)
        .map(([key, value]) => {
          const text = String(value)
          return { key, value: text.length > 60 ? text.slice(0, 59) + '…' : text }
        })
