      }

      const span = entries.reduce((sum, entry) => sum + entry.ms, 0) || 1
      let left = 0
      return entries.map((entry, index) => {
        const widthPct = (entry.ms / span) * 100
        const segment = {
          ...entry,
          key: `${entry.kind}-${index}`,
          width: widthPct + '%',
          leftPct: left,
          spanPct: widthPct,
          ...this.describeSegment(entry)
